from pathlib import Path
import json,hashlib,datetime,sys
s=Path(__file__).resolve().parent;label,rel,a,b=sys.argv[1],sys.argv[2],int(sys.argv[3]),int(sys.argv[4]);reg=json.loads((s/'SOURCE-DEPENDENCY-REGISTRATION.json').read_text());assert any(a>=lo and b<=hi for lo,hi in reg['windows'][rel]);raw=(s/'sources'/reg['revision']/rel).read_bytes();lines=raw.decode().splitlines();assert 1<=a<=b<=len(lines);text=f'SOURCE {rel}:{a}-{b}\n'+''.join(f'{i:4} {lines[i-1]}\n' for i in range(a,b+1)); name=f'SOURCE-DEPENDENCY-DISPLAY-{label}.txt';(s/name).write_text(text);rec={'source':rel,'range':[a,b],'source_sha256':hashlib.sha256(raw).hexdigest(),'display':name,'display_sha256':hashlib.sha256(text.encode()).hexdigest(),'at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'complete requested range'};(s/f'SOURCE-DEPENDENCY-RECEIPT-{label}.json').write_text(json.dumps(rec,indent=2)+'\n');print(text,end='')
